import React, { useState, useMemo } from 'react';
import Navbar from './components/Navbar';
import ProductCard from './components/ProductCard';
import CartModal from './components/CartModal';
import { Sparkles, TrendingUp, ShieldCheck, Truck, RotateCcw, CheckCircle2, Package, Layers, BarChart3 } from 'lucide-react';

const INITIAL_PRODUCTS = [
  {
    id: 1,
    name: 'Zenith Quantum Headphones',
    category: 'Audio',
    price: 299.99,
    rating: 4.9,
    badge: 'Best Seller',
    description: 'Active noise-canceling with 40-hour spatial audio playback and titanium acoustic drivers.',
    image: 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=800&q=80'
  },
  {
    id: 2,
    name: 'Aura Minimalist Mechanical Keyboard',
    category: 'Keyboards',
    price: 189.00,
    rating: 4.8,
    badge: 'New Arrival',
    description: 'Hot-swappable tactile switches, gasket-mounted aluminum body with per-key RGB backlighting.',
    image: 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?w=800&q=80'
  },
  {
    id: 3,
    name: 'Titan Smart Ergonomic Mouse',
    category: 'Accessories',
    price: 119.50,
    rating: 4.7,
    badge: 'Popular',
    description: 'Precision 8K sensor, dual-mode Bluetooth + 2.4GHz wireless with hyper-fast scroll wheel.',
    image: 'https://images.unsplash.com/photo-1527864550417-7fd91fc51a46?w=800&q=80'
  },
  {
    id: 4,
    name: 'Nebula 4K UltraWide Studio Display',
    category: 'Displays',
    price: 749.00,
    rating: 5.0,
    badge: 'Staff Pick',
    description: '144Hz refresh rate, 99% DCI-P3 color gamut with 90W USB-C single-cable power delivery.',
    image: 'https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?w=800&q=80'
  },
  {
    id: 5,
    name: 'Carbon Fiber MagSafe Stand',
    category: 'Accessories',
    price: 64.99,
    rating: 4.6,
    badge: '',
    description: 'Aerospace-grade carbon weave with dual adjustable pivot angles and 15W Qi2 wireless charging.',
    image: 'https://images.unsplash.com/photo-1586105251261-72a756497a11?w=800&q=80'
  },
  {
    id: 6,
    name: 'Zenith Studio Desk Mat Pro',
    category: 'Accessories',
    price: 49.00,
    rating: 4.9,
    badge: 'Essentials',
    description: 'Micro-weave water-resistant surface with non-slip natural rubber base and anti-fray stitching.',
    image: 'https://images.unsplash.com/photo-1616440347437-b1c73416efc2?w=800&q=80'
  }
];

const CATEGORIES = ['All Products', 'Audio', 'Keyboards', 'Displays', 'Accessories'];

export default function App() {
  const [products] = useState(INITIAL_PRODUCTS);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeCategory, setActiveCategory] = useState('All Products');
  const [cart, setCart] = useState([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [toastMessage, setToastMessage] = useState(null);
  const [addedItemIds, setAddedItemIds] = useState(new Set());
  const [viewMode, setViewMode] = useState('store'); // 'store' | 'admin'

  const showToast = (msg) => {
    setToastMessage(msg);
    setTimeout(() => setToastMessage(null), 3000);
  };

  const handleAddToCart = (product) => {
    setCart((prev) => {
      const existing = prev.find((item) => item.id === product.id);
      if (existing) {
        return prev.map((item) =>
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });

    setAddedItemIds((prev) => new Set([...prev, product.id]));
    setTimeout(() => {
      setAddedItemIds((prev) => {
        const next = new Set(prev);
        next.delete(product.id);
        return next;
      });
    }, 1500);

    showToast(`Added ${product.name} to cart!`);
  };

  const handleUpdateQuantity = (id, newQty) => {
    if (newQty <= 0) {
      handleRemoveItem(id);
      return;
    }
    setCart((prev) =>
      prev.map((item) => (item.id === id ? { ...item, quantity: newQty } : item))
    );
  };

  const handleRemoveItem = (id) => {
    setCart((prev) => prev.filter((item) => item.id !== id));
  };

  const handleCheckout = () => {
    alert('Thank you for your order! Your simulated checkout is complete.');
    setCart([]);
    setIsCartOpen(false);
    showToast('Order confirmed successfully!');
  };

  const filteredProducts = useMemo(() => {
    return products.filter((p) => {
      const matchesCategory =
        activeCategory === 'All Products' || p.category === activeCategory;
      const matchesSearch =
        p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        p.description.toLowerCase().includes(searchTerm.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [products, activeCategory, searchTerm]);

  const totalCartQuantity = cart.reduce((acc, item) => acc + item.quantity, 0);

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col relative overflow-x-hidden selection:bg-violet-500/30 selection:text-violet-200">

      {/* Ambient Light Glows */}
      <div className="absolute top-0 left-1/4 w-96 h-96 bg-violet-600/15 rounded-full blur-[140px] pointer-events-none" />
      <div className="absolute top-1/3 right-10 w-96 h-96 bg-cyan-500/10 rounded-full blur-[140px] pointer-events-none" />

      {/* Toast Notification */}
      {toastMessage && (
        <div className="fixed bottom-6 right-6 z-50 animate-bounce">
          <div className="flex items-center gap-2 bg-slate-900/95 border border-emerald-500/40 text-emerald-300 px-4 py-3 rounded-xl shadow-2xl backdrop-blur-xl text-sm font-semibold">
            <CheckCircle2 className="w-4 h-4 text-emerald-400" />
            <span>{toastMessage}</span>
          </div>
        </div>
      )}

      {/* Navigation */}
      <Navbar
        cartCount={totalCartQuantity}
        onOpenCart={() => setIsCartOpen(true)}
        searchTerm={searchTerm}
        onSearchChange={setSearchTerm}
        activeCategory={activeCategory}
        onCategoryChange={setActiveCategory}
        categories={CATEGORIES}
      />

      {/* Hero Banner */}
      <section className="relative py-12 md:py-16 px-4 sm:px-6 lg:px-8 max-w-7xl mx-auto w-full">
        <div className="backdrop-blur-2xl bg-gradient-to-r from-violet-900/20 via-slate-900/40 to-cyan-900/20 border border-white/10 rounded-3xl p-8 md:p-12 relative overflow-hidden shadow-2xl">
          <div className="max-w-2xl relative z-10">
            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-violet-500/10 border border-violet-500/30 text-violet-300 text-xs font-semibold mb-4">
              <Sparkles className="w-3.5 h-3.5" /> Next-Gen Workspace Gear
            </div>
            <h1 className="text-3xl md:text-5xl font-extrabold tracking-tight text-white mb-4 leading-tight">
              Elevate Your Desk Setup with <span className="bg-gradient-to-r from-violet-400 via-fuchsia-400 to-cyan-400 bg-clip-text text-transparent">EcommerceStore</span>
            </h1>
            <p className="text-slate-300 text-sm md:text-base leading-relaxed mb-6">
              Precision-engineered hardware and studio accessories designed for modern creators, developers, and power users.
            </p>
            <div className="flex flex-wrap items-center gap-4">
              <button
                onClick={() => setActiveCategory('All Products')}
                className="px-6 py-3 bg-gradient-to-r from-violet-600 via-fuchsia-600 to-cyan-600 rounded-xl font-bold text-sm text-white shadow-xl shadow-violet-500/25 hover:scale-[1.02] transition-all"
              >
                Shop Collection
              </button>
              <div className="flex items-center gap-6 text-xs text-slate-400 pl-2">
                <span className="flex items-center gap-1.5"><Truck className="w-4 h-4 text-cyan-400" /> Free Global Delivery</span>
                <span className="flex items-center gap-1.5"><RotateCcw className="w-4 h-4 text-violet-400" /> 30-Day Guarantee</span>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Main Products Grid */}
      <main className="flex-1 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 w-full pb-16">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h2 className="text-xl font-bold text-white tracking-tight">
              {activeCategory}
            </h2>
            <p className="text-xs text-slate-400 mt-0.5">
              Showing {filteredProducts.length} premium products
            </p>
          </div>
        </div>

        {filteredProducts.length === 0 ? (
          <div className="text-center py-16 bg-white/[0.02] border border-white/5 rounded-2xl p-8">
            <Package className="w-12 h-12 mx-auto mb-3 text-slate-600" />
            <h3 className="text-base font-bold text-slate-200 mb-1">No products found</h3>
            <p className="text-xs text-slate-400">Try adjusting your search query or filter category.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredProducts.map((product) => (
              <ProductCard
                key={product.id}
                product={product}
                onAddToCart={handleAddToCart}
                isAdded={addedItemIds.has(product.id)}
              />
            ))}
          </div>
        )}
      </main>

      {/* Cart Modal */}
      <CartModal
        isOpen={isCartOpen}
        onClose={() => setIsCartOpen(false)}
        cartItems={cart}
        onUpdateQuantity={handleUpdateQuantity}
        onRemoveItem={handleRemoveItem}
        onCheckout={handleCheckout}
      />

      {/* Footer */}
      <footer className="border-t border-white/10 bg-slate-950/80 py-8 px-4 sm:px-6 lg:px-8 text-center text-xs text-slate-500">
        <div className="max-w-7xl mx-auto flex flex-col sm:flex-row items-center justify-between gap-4">
          <p>© 2026 EcommerceStore Technologies Inc. All rights reserved.</p>
          <div className="flex items-center gap-4">
            <span className="hover:text-slate-300 cursor-pointer">Privacy Policy</span>
            <span className="hover:text-slate-300 cursor-pointer">Terms of Service</span>
            <span className="hover:text-slate-300 cursor-pointer">Support</span>
          </div>
        </div>
      </footer>
    </div>
  );
}

export default function Checkout() {
  return (
    <section id="checkout" className="py-20">
      <div className="max-w-4xl mx-auto px-6 text-slate-700">
        <h2 className="text-3xl font-bold mb-4">Checkout</h2>
      </div>
    </section>
  );
}

import React, { useState, useMemo } from 'react';
import { Search, Filter, ShoppingBag, Calendar, Star, Heart, Sparkles, ChevronRight, ExternalLink } from 'lucide-react';

const MOCK_CATEGORIES = ['Arabica', 'Robusta', 'Decaf', 'Espresso', 'Espresso Pods'];
const MOCK_BRANDS = ['African Elite', 'Ethiopian Blend', 'Sumatra Roast'];

const initialProducts = [
  {
    id: 1,
    name: 'Sumatra Dark Roast',
    brand: 'Ethiopian Blend',
    price: 29.99,
    rating: 4.8,
    reviews: 124,
    stock: 'Low',
    description: 'Rich and earthy, with notes of dark chocolate and smoke.',
    category: 'Arabica',
    imageUrl: 'https://images.unsplash.com/photo-1514521949494-7b13b6b4a3f0?w=800&q=80&fm=avif',
    tags: ['organic', 'fair-trade'],
  },
  {
    id: 2,
    name: 'Kona Mild',
    brand: 'African Elite',
    price: 34.50,
    rating: 4.9,
    reviews: 152,
    stock: 'In Stock',
    description: 'Smooth and balanced, with hints of citrus and vanilla.',
    category: 'Robusta',
    imageUrl: 'https://images.unsplash.com/photo-1532005011789-a0a0c1b2a50d?w=800&q=80&fm=avif',
    tags: ['single-origin', 'shade-grown'],
  },
  {
    id: 3,
    name: 'Decaf Supreme',
    brand: 'Ethiopian Blend',
    price: 26.99,
    rating: 4.7,
    reviews: 89,
    stock: 'Medium',
    description: 'Gentle caffeine removal process preserves full flavor and aroma.',
    category: 'Decaf',
    imageUrl: 'https://images.unsplash.com/photo-1542808106-68b8a79b6c6b?w=800&q=80&fm=avif',
    tags: ['organic', 'cold-brew'],
  },
];

export default function ProductCatalog() {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('All');
  const [isWishlist, setIsWishlist] = useState(false);
  const [activeSort, setActiveSort] = useState('default');

  const filteredProducts = useMemo(() => {
    return initialProducts.filter((item) => {
      const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'All' || item.category === filterCategory;
      return matchesSearch && matchesCategory;
    });
  }, [searchTerm, filterCategory]);

  const handleSort = (value) => {
    setActiveSort(value);
    const sortFunc = (a, b) => {
      if (value === 'rating') return b.rating - a.rating;
      if (value === 'price') return a.price - b.price;
      return 0;
    };
    filteredProducts.sort(sortFunc);
  };

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4 sm:p-6 lg:p-8">
      <div className="w-full max-w-6xl mx-auto bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-6 sm:p-8 shadow-2xl">

        {/* Header & Filters */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-8">
          <div>
            <h2 className="text-2xl font-bold text-slate-100 flex items-center gap-2">
              <Sparkles className="w-5 h-5 text-amber-400 animate-pulse" /> 
              Premium Coffee Bean Catalog
            </h2>
            <p className="text-slate-400 mt-2 text-sm">Explore our carefully sourced coffee beans for cafes and enthusiasts.</p>
          </div>
          <div className="flex flex-wrap gap-3 sm:gap-4">
            <div className="flex items-center gap-2">
              <span className="text-xs font-semibold text-slate-400 bg-slate-900/20 p-1 rounded-full">Wishlist</span>
              <button
                onClick={() => setIsWishlist(!isWishlist)}
                className="px-3 py-2 bg-slate-900 text-sm font-medium text-slate-300 border border-slate-900/40 rounded-lg transition-all duration-200 hover:bg-slate-800"
              >
                {isWishlist ? 'Active Wishlist' : 'Toggle Wishlist'}
              </button>
            </div>
            <button
              onClick={() => setFilterCategory('All')}
              className="px-3 py-2 bg-slate-900 text-sm font-medium text-slate-300 border border-slate-900/40 rounded-lg transition-all duration-200 hover:bg-slate-800"
            >
              All
            </button>
            {MOCK_CATEGORIES.map((cat) => (
              <button
                key={cat}
                onClick={() => setFilterCategory(cat)}
                className="px-3 py-2 bg-slate-900 text-sm font-medium text-slate-300 border border-slate-900/40 rounded-lg transition-all duration-200 hover:bg-slate-800"
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

        {/* Search & Sort */}
        <div className="sm:flex sm:items-center sm:justify-between mb-8">
          <div className="flex flex-wrap sm:flex-nowrap sm:gap-4">
            <div className="flex items-center gap-2">
              <Search className="w-4 h-4 text-slate-400" />
              <input
                onChange={(e) => setSearchTerm(e.target.value)}
                value={searchTerm}
                type="text"
                placeholder="Search beans..."
                className="bg-slate-900 text-slate-200 border border-slate-900/40 rounded-lg px-3 py-2 text-sm placeholder:text-slate-500 outline-none transition-all duration-200 placeholder:text-slate-400 active:border-white/10 focus:ring-2 focus:ring-indigo-500"
              />
            </div>
            <div className="flex items-center gap-2">
              <div className="flex items-center gap-1 text-xs font-semibold text-slate-400">
                Sort by:
                <button
                  onClick={() => handleSort('default')}
                  className="px-3 py-1 border border-slate-900/20 rounded-lg text-slate-300 transition-colors active:text-white"
                >
                  Default
                </button>
                <button
                  onClick={() => handleSort('rating')}
                  className="px-3 py-1 border border-slate-900/20 rounded-lg text-slate-300 transition-colors active:text-white"
                >
                  Rating
                </button>
                <button
                  onClick={() => handleSort('price')}
                  className="px-3 py-1 border border-slate-900/20 rounded-lg text-slate-300 transition-colors active:text-white"
                >
                  Price
                </button>
              </div>
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-3 sm:gap-4">
            <button className="px-4 py-2 rounded-lg bg-indigo-600/10 border border-indigo-600/20 text-indigo-400 hover:text-indigo-300 transition-colors active:scale-95">
              <Sparkles className="w-4 h-4 mr-2" /> Featured
            </button>
            <button className="px-4 py-2 rounded-lg bg-emerald-600/10 border border-emerald-600/20 text-emerald-400 hover:text-emerald-300 transition-colors active:scale-95">
              <Heart className="w-4 h-4 mr-2" /> Wishlist
            </button>
          </div>
        </div>

        {/* Product Grid */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {filteredProducts.map((item) => (
            <div
              key={item.id}
              className="group relative overflow-hidden rounded-2xl border border-white/10 p-6 transition-all duration-300 hover:scale-[1.02] hover:border-white/20 hover:shadow-2xl"
            >
              {/* Top Gradient Badge */}
              {item.stock === 'Low' && (
                <div className="absolute -top-3 -right-3 rounded-xl bg-indigo-600/20 px-3 py-1.5 text-xs font-medium text-indigo-300 backdrop-blur-xl">
                  <StockBadge type={item.stock} />
                </div>
              )}
              {/* Bottom Gradient Badge */}
              {item.tags.length > 0 && (
                <div className="absolute -bottom-3 -right-3 rounded-xl bg-violet-600/20 px-3 py-1.5 text-xs font-medium text-violet-300 backdrop-blur-xl">
                  {item.tags.map((tag, i) => (
                    <span key={tag} className="mr-1.5 rounded-full bg-violet-500/20 px-2.5 py-0.5 text-[10px] tracking-wider">
                      {tag}
                    </span>
                  ))}
                </div>
              )}

              {/* Coffee Bean Image */}
              <div className="relative h-48 w-full overflow-hidden rounded-xl bg-slate-900/70 transition-all duration-500 group-hover:scale-[1.02] group-hover:blur-0 group-hover:bg-white/10">
                <img
                  src={item.imageUrl}
                  alt={item.name}
                  className="h-full w-full object-cover transition-all duration-500 group-hover:scale-[105%]"
                />
                <div className="absolute bottom-6 left-6 flex flex-col items-start gap-1.5">
                  {item.rating > 0 && (
                    <div className="flex items-center gap-1">
                      <Star className="w-4 h-4 text-amber-400" />
                      <span className="text-[10px] font-semibold text-slate-400">{item.rating}</span>
                    </div>
                  )}
                  {item.stock !== 'In Stock' && (
                    <div className="flex items-center gap-1 text-[10px] text-slate-400">
                      <Calendar className="w-3.5 h-3.5 text-slate-500" />
                      <span>{item.stock}</span>
                    </div>
                  )}
                </div>
              </div>

              {/* Bottom Card Info */}
              <div className="mt-6 flex flex-col justify-between space-y-4">
                <div className="flex flex-col gap-2">
                  <h3 className="text-slate-100 text-xl font-semibold tracking-tight hover:underline transition-all">
                    {item.name}
                  </h3>
                  <p className="text-sm text-slate-400">{item.brand}</p>
                  <p className="text-sm text-slate-400">{item.category}</p>
                </div>
                <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-2">
                  <div className="flex flex-col items-end gap-1.5">
                    <p className="text-lg font-bold text-slate-100">$ {item.price.toFixed(2)}</p>
                    {isWishlist && (
                      <button
                        className="px-2.5 py-1 rounded-full bg-white/10 border border-white/20 text-slate-400 text-[10px] font-medium transition-colors hover:text-white active:scale-95"
                      >
                        <ExternalLink className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                  <button
                    onClick={() => setIsWishlist(!isWishlist)}
                    className="px-3 py-2 rounded-lg bg-white/5 border border-white/10 text-slate-300 hover:text-white transition-colors"
                  >
                    {isWishlist ? 'Removed from Wishlist' : 'Add to Wishlist'}
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>

      </div>
    </div>
  );
}

const StockBadge = ({ type }) => {
  const badgeStyle = {
    'In Stock': 'bg-emerald-500/20 text-emerald-300 border-emerald-500/30',
    'Low': 'bg-amber-500/20 text-amber-300 border-amber-500/30',
    'Out of Stock': 'bg-rose-500/20 text-rose-300 border-rose-500/30',
  }[type];
  return (
    <div className={`rounded-full px-3 py-1 text-xs font-semibold ${badgeStyle}`}>
      {type.charAt(0).toUpperCase() + type.slice(1)}
    </div>
  );
};

export default function Subscriptions() {
  return (
    <section id="subscriptions" className="py-20">
      <div className="max-w-4xl mx-auto px-6 text-slate-700">
        <h2 className="text-3xl font-bold mb-4">Subscriptions</h2>
      </div>
    </section>
  );
}
